import csv,json
from geometry import ROOT

def table(rows,keys,labels):
 return '\n'.join(['| '+' | '.join(labels)+' |','|'+'|'.join(['---']*len(keys))+'|']+['| '+' | '.join(str(r[k]) for k in keys)+' |' for r in rows])
def run():
 rows=list(csv.DictReader((ROOT/'size_comparison.csv').open()));br=list(csv.DictReader((ROOT/'crossing_brackets_18.csv').open()));val=json.loads((ROOT/'validation.json').read_text());f36=json.loads((ROOT/'feasibility36.json').read_text());cost=list(csv.DictReader((ROOT/'computational_costs.csv').open()));lines=['# 유한 크기 허브 편극과 림 스핀 보상: 검증 결과','18스핀 두 형상의 전 운동량 ED와 27스핀 검증 자료의 동일 정규화 비교를 완료했다. 36스핀에서는 실제 고자화 기저·행렬–벡터 곱 파일럿만 수행했으며, 저스핀 바닥상태 에너지는 계산하지 않았다. 측정, 재사용한 검증 자료, 자원 추정을 구분한다.','핵심 결과는 허브 강자성 상관의 급증과 이후 림 균일 총스핀 상관의 증가·전체 스핀 감소가 두 18스핀 형상과 27스핀에서 반복된다는 것이다. 그러나 교차 위치와 스핀 플래토는 일치하지 않는다. 이는 기작의 유한계 재현을 지지하지만 열역학적 상전이를 확정하지 않는다.']
 x=[]
 for r in br:x.append({'shape':r['shape'],'change':r['S_lo']+' → '+r['S_hi'],'bracket':f"[{float(r['r_lo']):.10f}, {float(r['r_hi']):.10f}]",'width':f"{float(r['width']):.8f}",'estimate':f"{float(r['secant_intersection_estimate']):.10f}"})
 lines+=['검증된 18스핀 교차 구간은 다음과 같다. 할선 교점은 보간 추정이며, 그 결합에서도 별도 ED를 수행해 두 가지의 에너지 차 부호를 확인하고 구간을 좁혔다. 추정값 자체를 정확한 임계점으로 취급하지 않는다.',table(x,['shape','change','bracket','width','estimate'],['형상','총스핀 변화','실측 끝점 구간','폭','초기 할선 추정'])]
 out=[]
 for shape in ['K18','C18','N27']:
  for r in [.2,.35,.4,.5,.6,.7]:
   match=[q for q in rows if q['shape']==shape and abs(float(q['r'])-r)<1e-8]
   for q in match:out.append({'shape':shape,'r':r,'S':q['S'],'p':f"{float(q['p_H']):.6f}",'H2':f"{float(q['H2']):.6f}",'R2':f"{float(q['R2']):.6f}",'N2':f"{float(q['m_N2']):.6f}",'m':f"{float(q['m_tot']):.6f}"})
 lines+=['대표점의 관측량은 다음과 같다. 27스핀에 실제 계산 자료가 없는 r=0.4 등의 점은 보간하여 채우지 않았다.',table(out,['shape','r','S','p','H2','R2','N2','m'],['형상','r','S','p_H','H²','R²','m_N²','S/N'])]
 lines+=['K18은 T₁=(3,0), T₂=(2,2)이며 가우스 축소 후 길이 3과 3√3, 각도 90°인 직사각형 토러스이다. 지수 6인 모든 12개 부분격자를 검사했으며, 유효한 k₀-허용 세 형상은 모두 점군으로 동등하다. 더 등방적인 독립 K-허용 18스핀 형상은 없다. C18 대조군 T₁=(1,2), T₂=(0,6)은 축소 길이 √12와 √21, 각도 79.11°이며 약결합 셀 운동량 k₀=(1/3,2/3)를 허용하지 않는다. 두 형상을 하나의 K-섹터 외삽에 섞지 않았다.','K18의 약결합 바닥상태는 셀 k=(0,1/2), S=0이고 첫 교차 후 Γ, S=2로 바뀐다. C18의 검출된 바닥상태는 Γ에 머물며 S=0→2→1→0 순서이다. K18에서는 r≤0.7 동안 S=0→2→1만 검출되었다. 27스핀은 검증된 표에서 1/2→7/2→5/2→3/2→1/2 순서를 보인다. 27스핀의 첫 두 실측 구간은 [0.25625,0.2609375], [0.3875,0.3921875]이고, 0.2577224979 및 0.3903174730은 기존 보간 추정이다. 이후 두 변화는 이 자료에서 각각 [0.5,0.6], [0.6,0.7] 사이의 샘플 변화로만 알려져 있다.','기하 차이는 작지 않다. 짧은 주기 길이는 K18에서 3, C18에서 3.4641, 27스핀에서 5.1962, 36스핀 후보에서 6이다. r=1에서 두 18스핀 형상은 물리 M 점 중 (1/2,1/2) 하나만 허용하고, 27스핀은 하나도 허용하지 않으며, 36스핀 후보는 세 M 점을 모두 허용한다. r≠1에서는 물리 원시 운동량이 대칭 양자수가 아니므로 18스핀의 약결합 셀 (0,1/2)를 자동으로 물리 M 상태라 부르지 않았다. k₀를 허용하는 것만으로 형상이 27스핀과 비슷해지거나 허브 구조인자의 최대 운동량이 k₀가 되는 것은 아니다. 전체 허용 q의 스핀 합산 S_h(q)와 최대점은 CSV에 별도로 제공한다. 물리 삼각 격자의 K=(1/3,2/3)는 세 사이트 셀 Γ로 접히며 약결합 셀 k₀와 구별했다.','p_H의 유한계 하한도 크기·짝홀성에 의존한다. 짝수 N_H에서는 −3/(N_H−1), 홀수 N_H에서는 −3/N_H이다. 따라서 약결합에서 18스핀의 약 −0.59와 27스핀의 약 −0.327은 모두 각자의 작은 허브 총스핀 한계에 가깝다. 이 수치 차이만으로 다른 벌크 상태를 주장할 수 없다. 강한 허브 편극 이후 R²가 커지고 S/N이 작아지는 경향은 공통적이다. 반면 r=0.7에서 K18은 S=1, C18은 S=0, N27은 S=1/2로 남아 정량적인 유한 형상 의존성이 크다.','H²와 R²는 보존되는 별도 스핀 양자수가 아니다. 직접 연산자 작용으로 계산한 분산은 `subsystem_spin_variances_18.csv`와 `reference27_checkpoint_audit.json`에 있으며 일반적으로 0이 아니다. 단단한 허브·림 스핀을 가정하는 회전자 그림은 해석적 모형일 뿐 이 ED가 별도 순수 스핀 상태를 증명하지 않는다.']
 lines+=['정규화는 모든 크기에서 동일하다. m_tot=S/N이며 sqrt[S(S+1)]/N은 별도 열이다. H²+R²+2HR=S(S+1), p_H=[H²−3N_H/4]/[N_H(N_H−1)/4], m_R,uniform²=R²/N_R², m_N²=⟨(Σ_R(S_A−S_B))²⟩/N_R²이다. C(q)는 셀 수로 나눈 스핀 합산 푸리에 행렬이며 F_N(Γ)=4N_cell m_N², 정규화된 (A−B)/√2 모드의 값은 2N_cell m_N²이다. S_h(q)=Σ_RR′ exp[−2πiq·(R′−R)]⟨T_R·T_R′⟩/N_H이다. zz 표는 SU(2) 다중항 평균을 뜻할 때만 S_h/3이다. M=0 또는 M=1/2에서 선택한 상태의 총자화와 S/N을 혼동하지 않았다.']
 lines += [f"검증된 18스핀 결합/형상 조합은 {val['number_of_18spin_couplings_and_shapes']}개이며 운동량 최소값 {val['number_of_18spin_momentum_minima']}개와 낮은 고유상태 {val['number_of_18spin_returned_eigenpairs']}개를 기록했다. 모든 정수-S 다중항이 M=0을 포함하고 평행이동이 SU(2)와 가환하므로 전 여섯 운동량의 M=0 탐색은 전 스핀 바닥상태를 포함한다. 최대 바닥상태 H 잔차는 {val['max_ground_H_residual']:.3e}, S² 잔차는 {val['max_ground_S2_residual']:.3e}, 스핀 합규칙 오차는 {val['max_18spin_total_spin_sum_rule_error']:.3e}이다. 교차 근처 세 점의 작은 스핀 혼합은 H와 S²의 공동 부분공간 대각화 후 각 스핀 안에서 H를 다시 대각화하여 제거했다. 에너지 변화는 6×10⁻¹⁵ 미만이다."]
 lines += ['독립 12스핀 전체 행렬과 모든 축소 운동량 블록을 비교하고 전체 스펙트럼도 재현했다. 18스핀의 대칭을 쓰지 않은 48,620차원 M=0 계산은 r=0.4와 1에서 전 운동량 ED의 에너지를 약 2×10⁻¹⁴ 이내로 재현했다. r=0은 림 싱글릿×자유 허브 시험 상태로 확인했으며, 허브가 축퇴하므로 고유한 편극을 부여하지 않았다. r=1에서는 18/27/36 그래프가 의도한 삼각 격자 최근접 이웃 그래프임을 독립 좌표 구성으로 검증했다. 27스핀 12개 실공간 행렬을 같은 정의로 다시 처리하고 다섯 실제 체크포인트의 H, S², H², R²를 직접 재검사했다.','전체 스윕 외에 0.0125 간격의 격자로 추가 상태 변화를 점검했다. 다만 변화가 없는 두 끝점 사이에 임의로 좁은 재진입 상태가 없음을 수학적으로 증명한 것은 아니다. 표와 그림은 검출된 유한계 교차를 표시한다.']
 lines += [f"36스핀 조건부 단계: 기하·운동량을 검증하고 Burnside 문자식으로 Sᶻ=0 차원 {f36['exact_Sz0_full_dimension']:,} 및 각 운동량 차원을 정확히 계산했다. Γ 차원은 {f36['exact_translation_sector_dimensions'][0]['dimension']:,}이다. 복소 벡터 하나가 최소 {f36['smallest_complex_vector_GiB']:.3f} GiB, Γ의 실수 벡터도 {f36['Gamma_real_vector_GiB']:.3f} GiB이다. 현재 조합순위 인덱스의 보조 배열만 {f36['dense_combinatorial_lookup_GiB']:.2f} GiB가 필요하므로 8 GiB에서 저스핀 기저를 무리하게 할당하지 않았다."]
 p=f36['measured_pilots'][-1];lines += [f"대신 실제 36사이트 Hamiltonian을 r=0.3, |Sᶻ|=14와 12에서 시험했다. |Sᶻ|=12의 전체 차원은 {p['full_sector_dim']:,}, Γ 축소 차원은 {p['translation_Gamma_dim']:,}이며 H|v⟩ 중앙 시간은 {p['median_H_action_seconds']:.6f}초, 기저 생성은 {p['basis_generation_seconds']:.6f}초였다. 독립 Python 전체 2-다운-스핀 계산과 64비트 C++ 축소 작용도 약 1.3×10⁻¹⁴ 이내에서 일치했다. 이는 고자화 파일럿이며 36스핀 바닥상태나 저스핀 에너지를 확인한 결과가 아니다. `results_36.csv`는 파일럿만 담는다."]
 lines += [f"차원에 비례시킨 저스핀 H 작용 추정은 현재 두 CPU에서 약 {f36['translation_only_Sz0_H_seconds_estimate_from_high_Sz_pilot']:.1f}초/회, 가정한 300–1000회는 {f36['hypothetical_300_to_1000_H_actions_hours_at_two_CPU_estimate'][0]:.1f}–{f36['hypothetical_300_to_1000_H_actions_hours_at_two_CPU_estimate'][1]:.1f}시간이다. 이는 측정된 저스핀 성능이 아니며 반충전에서 더 많은 반대 스핀 결합과 순위 계산 때문에 낙관적일 수 있다. 추가 점군 축소와 인덱싱을 설계하더라도 선택적 Γ 섹터는 약 128 GiB, Γ/코너 등 바닥상태 검증 범위는 약 256 GiB·64–128 CPU 코어를 출발 설계로 권한다. 보장된 실행 사양은 아니다. 가장 작은 대안은 18/27 ED로 검증한 SU(2)-보존 DMRG를 36스핀 원통/토러스에 적용해 여러 결합차원과 에너지 분산·절단 오차를 확인하는 것이다. 원통의 경계 효과도 따로 비교해야 한다."]
 wall=sum(float(x['wall_seconds']) for x in cost);peak=max(float(x['peak_process_RSS_MiB']) for x in cost);hc=sum(int(x['H_calls']) for x in cost);lines += [f"18스핀 기록의 단계별 벽시계 시간 합은 {wall/60:.2f}분, 기록된 H 작용은 {hc:,}회, 최대 프로세스 RSS는 {peak:.2f} MiB였다. 두 형상은 일부 동시 실행했으므로 시간 합은 전체 경과 시간이 아니다. 체크포인트 압축 시간과 보조 S² 작용을 모두 H 카운터에 넣은 것은 아니며, 별도 검증/파일럿 단계는 `phase_records.json`에 기록했다. CPU 모델·할당은 환경 파일, 상태별 호출 수·시간·메모리는 CSV/JSON에 있다."]
 lines += ['이 계산은 두 작은 크기에서 허브 편극과 림 보상 기작이 반복됨을 확인한다. 다만 18/27만으로 장거리 질서, 열역학적 임계 결합 또는 안정한 벌크 페리자성 구간을 결정하지 않는다. 36스핀 저스핀 ED를 완료했다고 주장하지 않는다.']
 (ROOT/'PHYSICS_REPORT.md').write_text('\n\n'.join(lines));print('Physics report written.')
if __name__=='__main__':run()
